namespace CleanArchitecture.Blazor.Application.Features.Systems.EventHandlers;

public class SystemDeletedEventHandler : INotificationHandler<SystemDeletedEvent>
{
    private readonly ILogger<SystemDeletedEventHandler> _logger;

    public SystemDeletedEventHandler(
        ILogger<SystemDeletedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SystemDeletedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("System deleted: {SystemName} (ID: {SystemId}) by {DeletedBy}", 
            notification.Item.Name, 
            notification.Item.Id, 
            notification.Item.LastModifiedBy);
        
        return Task.CompletedTask;
    }
}